<script setup lang="ts">
import {ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,money,statusName} from './api'
import ActionDialog from './ActionDialog.vue'
const draft=ref<any>(null)
const route=useRoute(),items=ref<any[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),payment=ref<any>(null),payBusy=ref(false),notice=ref(''),flash=ref('')
let generation=0
async function load(){const g=++generation;busy.value=true;error.value='';try{const data=await api(`/api/my/${route.path==='/coupons'?'vouchers':'orders'}?page=${page.value}`);if(g===generation){items.value=data.items;total.value=data.total}}catch(e){if(g===generation)error.value=(e as Error).message}finally{if(g===generation)busy.value=false}}
watch(()=>route.path,()=>{page.value=1;items.value=[];payment.value=null;load()},{immediate:true})
function id(o:any){return o.orderId||o.order_id||String(o.id)}
async function cancelOrder(o:any){busy.value=true;try{draft.value=await api(`/api/my/orders/${id(o)}/cancel/prepare`,'POST')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function openPay(o:any){busy.value=true;notice.value='';try{const data=await api(`/api/my/orders/${id(o)}`);if(data.status!==1||data.pay_cents<=0)throw new Error('订单已不是待支付状态，请刷新');payment.value=data}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function pay(){payBusy.value=true;notice.value='';flash.value='';try{const result=await api(`/api/my/orders/${payment.value.order_id}/pay/mock`,'POST',{confirmed:true,expected_pay_cents:payment.value.pay_cents});payment.value=null;flash.value=result.notice||'模拟支付成功，不扣真实资金。';await load()}catch(e){notice.value=(e as Error).message+'。请关闭窗口刷新订单核实状态。';await load()}finally{payBusy.value=false}}
async function completeOrder(o:any){busy.value=true;try{await api(`/api/my/orders/${id(o)}/complete`,'POST');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page"><div class="row"><div><div class="eyebrow">{{route.path==='/coupons'?'YOUR WALLET':'YOUR ORDERS'}}</div><h2>{{route.path==='/coupons'?'我的券包':'我的订单'}}</h2><p class="muted">{{route.path==='/coupons'?'这里展示当前账号已领取或已支付的券。':'查看当前账号订单，付费券支付后进入券包。'}}</p></div><button class="outline" :disabled="busy" @click="load">刷新</button></div><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="flash" class="notice" role="status">{{flash}}</div><article class="voucher-row" v-for="o in items" :key="id(o)"><div><span class="pill">{{statusName(o.status)}}</span><h3>{{o.title||o.voucherTitle||o.voucher_title||'商品券'}}</h3><p>{{o.shopName||o.shop_name}}</p><p class="small muted">订单 {{id(o)}} · {{o.createTime||o.created_at}}</p><p class="small muted">{{o.rules}}</p></div><div><div class="price">¥{{money(o.payValue??o.pay_cents)}}</div><button v-if="o.status===1" class="primary" :disabled="busy" @click="openPay(o)">模拟支付</button><button v-if="o.status===1&&o.voucher_type===0" class="text-button" :disabled="busy" @click="cancelOrder(o)">取消订单</button><button v-if="o.status===2" class="primary" :disabled="busy" @click="completeOrder(o)">确认核销</button></div></article><div v-if="!busy&&!items.length" class="empty">{{route.path==='/coupons'?'暂时没有持有券。待支付订单不计入券包。':'暂时没有订单。可以从店铺详情或聊天推荐购买商品券。'}}</div><div class="pagination"><button class="outline" :disabled="busy||page===1" @click="page--;load()">上一页</button><span class="small muted">第 {{page}} 页 · 共 {{total}} 条</span><button class="outline" :disabled="busy||items.length===0||page*20>=total" @click="page++;load()">下一页</button></div><p class="small muted">仅支持本地模拟支付，不扣真实资金，不支持真实支付与退款。</p></div><ActionDialog v-if="draft" :key="draft.action_id" :draft="draft" @close="draft=null" @changed="load"/><div class="overlay" v-if="payment"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="pay-title"><button class="close" :disabled="payBusy" @click="payment=null">×</button><h2 id="pay-title">本地模拟支付</h2><div class="summary"><p>订单 {{payment.order_id}}</p><div class="price">¥{{money(payment.pay_cents)}}</div><p>{{statusName(payment.status)}}</p></div><p>确认后仅改变本地订单状态，<b>不扣真实资金</b>。</p><p v-if="notice" role="status">{{notice}}</p><div class="actions"><button class="outline" :disabled="payBusy" @click="payment=null">关闭</button><button class="primary" :disabled="payBusy||payment.status!==1" @click="pay">明确确认模拟支付</button></div></section></div></template>
